'use strict';
const POST_PREVIEW_LIMIT=300,expandedPosts=new Set(),openedComments=new Set(),commentDrafts=new Map(),savingComments=new Set();
let dateFrom='',dateTo='';
function bodyPreview(text,limit=POST_PREVIEW_LIMIT){let remaining=limit,out='',truncated=false;for(const part of String(text).split(/(\[\[image:[a-zA-Z0-9-]+\]\])/g)){if(/^\[\[image:[a-zA-Z0-9-]+\]\]$/.test(part)){if(remaining>0)out+=part;continue}const chars=Array.from(part);if(chars.length<=remaining){out+=part;remaining-=chars.length}else{out+=chars.slice(0,remaining).join('');truncated=true;break}}return {text:out,truncated}}
function localDateKey(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function inDateRange(post,start=dateFrom,end=dateTo){if(start&&end&&start>end)return false;const key=localDateKey(post.created);return (!start||key>=start)&&(!end||key<=end)}
const journalValid=valid;valid=function(d){return journalValid(d)&&d.posts.every(p=>p.comments===undefined||(Array.isArray(p.comments)&&new Set(p.comments.map(c=>c.id)).size===p.comments.length&&p.comments.every(c=>typeof c.id==='string'&&typeof c.body==='string'&&c.body.trim().length>0&&Number.isFinite(Date.parse(c.created))&&(c.updated===undefined||Number.isFinite(Date.parse(c.updated))))))};
const journalPosts=visiblePosts;visiblePosts=function(){return journalPosts().filter(p=>inDateRange(p))};
function commentMarkup(p){const comments=[...(p.comments||[])].sort((a,b)=>Date.parse(a.created)-Date.parse(b.created));return `<details class="postComments" data-comments-post="${esc(p.id)}" ${openedComments.has(p.id)?'open':''}><summary>评论 · ${comments.length}<span>给以后的想法，留一个位置</span></summary><div class="commentList">${comments.map(c=>`<article class="commentItem"><div class="commentMeta"><time datetime="${esc(c.created)}">${esc(new Date(c.created).toLocaleString('zh-CN'))}</time>${c.updated&&c.updated!==c.created?'<span>已编辑</span>':''}</div><div class="commentBody">${esc(c.body)}</div><div class="row"><button type="button" data-edit-comment="${esc(c.id)}" data-comment-post="${esc(p.id)}">编辑</button><button type="button" data-delete-comment="${esc(c.id)}" data-comment-post="${esc(p.id)}">删除</button></div></article>`).join('')||'<p class="hint">还没有补充想法。</p>'}</div><form data-comment-form="${esc(p.id)}"><label class="field" for="comment-${esc(p.id)}">写一条新的想法</label><textarea id="comment-${esc(p.id)}" name="comment" required maxlength="20000" placeholder="过了很久，又想到了……">${esc(commentDrafts.get(p.id)||'')}</textarea><div class="commentSubmit"><span class="hint">和帖子一起私人保存，并包含在备份中。</span><button class="primary" type="submit">保存评论</button></div></form></details>`}
const legacyFoldPosts=foldPosts;foldPosts=function(){if(['graph','gallery'].includes(view.type))return;if(view.type==='relations')return legacyFoldPosts();$('feed').querySelectorAll('article.post').forEach(article=>{const id=article.querySelector('[data-edit-post]')?.dataset.editPost,p=data.posts.find(p=>p.id===id);if(!p)return;article.classList.add('journalPost');article.dataset.postId=id;const meta=article.querySelector(':scope > .meta');if(meta){meta.classList.add('journalMeta');meta.textContent=new Date(p.created).toLocaleString('zh-CN')+(p.status==='draft'?' · 草稿':'')+(p.favorite?' · 已收藏':'')}const body=article.querySelector(':scope > .body'),preview=bodyPreview(p.body);if(preview.truncated){const expanded=expandedPosts.has(id);body.innerHTML=richText(expanded?p.body:preview.text)+(expanded?'':'…');body.id='post-body-'+id;const button=document.createElement('button');button.className='readMore';button.type='button';button.dataset.expandPost=id;button.setAttribute('aria-controls',body.id);button.setAttribute('aria-expanded',String(expanded));button.textContent=expanded?'收起正文':'展开全文（超过 '+POST_PREVIEW_LIMIT+' 字）';body.after(button)}if(p.status==='published'){const holder=document.createElement('div');holder.innerHTML=commentMarkup(p);article.append(holder.firstElementChild);article.querySelector('.postComments').addEventListener('toggle',e=>{if(e.target.open)openedComments.add(id);else openedComments.delete(id)})}})};
function syncDateControls(){const panel=$('postDates');if(!panel)return;panel.hidden=['graph','gallery','relations'].includes(view.type);const invalid=Boolean(dateFrom&&dateTo&&dateFrom>dateTo);$('dateRangeText').textContent=dateFrom||dateTo?`${dateFrom||'不限'} 至 ${dateTo||'不限'}`:'全部时间';$('dateError').textContent=invalid?'开始日期不能晚于结束日期。':'';$('postDateStart').setAttribute('aria-invalid',String(invalid));$('postDateEnd').setAttribute('aria-invalid',String(invalid));$('clearDates').hidden=!dateFrom&&!dateTo}
const journalFeed=renderFeed;renderFeed=function(){journalFeed();syncDateControls()};
function installDateFilter(){const panel=document.createElement('details');panel.id='postDates';panel.className='datePanel foldPanel';panel.innerHTML='<summary>按时间查找 <span id="dateRangeText">全部时间</span></summary><div class="dateControls"><label>开始日期<input id="postDateStart" type="date" aria-describedby="dateHelp dateError"></label><span class="dateSeparator">—</span><label>结束日期<input id="postDateEnd" type="date" aria-describedby="dateHelp dateError"></label><button type="button" id="recentWeek">近 7 天</button><button type="button" id="thisMonth">本月</button><button type="button" id="clearDates" hidden>清除日期</button></div><p class="hint" id="dateHelp">按发帖日期筛选，包含起止当天；可以只选一端。</p><p id="dateError" role="status"></p>';document.querySelector('.searchbar').after(panel);foldRemember(panel,'post-date-panel',false);const update=()=>{dateFrom=$('postDateStart').value;dateTo=$('postDateEnd').value;renderFeed()};$('postDateStart').onchange=update;$('postDateEnd').onchange=update;$('clearDates').onclick=()=>{$('postDateStart').value='';$('postDateEnd').value='';update()};$('recentWeek').onclick=()=>{const today=new Date(),start=new Date(today.getFullYear(),today.getMonth(),today.getDate()-6);$('postDateStart').value=localDateKey(start);$('postDateEnd').value=localDateKey(today);update()};$('thisMonth').onclick=()=>{const today=new Date();$('postDateStart').value=localDateKey(new Date(today.getFullYear(),today.getMonth(),1));$('postDateEnd').value=localDateKey(today);update()};syncDateControls()}
document.addEventListener('input',e=>{const form=e.target.closest('[data-comment-form]');if(form&&e.target.name==='comment')commentDrafts.set(form.dataset.commentForm,e.target.value)});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-comment-form]');if(!form)return;e.preventDefault();const postId=form.dataset.commentForm,body=form.elements.comment.value.trim();if(!body)return toast('先写一点想法吧。');if(savingComments.has(postId))return;const next=clone(),post=next.posts.find(p=>p.id===postId);if(!post)return toast('这篇帖子已不存在。');post.comments??=[];post.comments.push({id:uid(),body,created:new Date().toISOString()});openedComments.add(postId);commentDrafts.delete(postId);savingComments.add(postId);const button=form.querySelector('button[type=submit]');button.disabled=true;try{if(await commit(next))toast('新想法已保存。');else commentDrafts.set(postId,body)}finally{savingComments.delete(postId);if(button.isConnected)button.disabled=false}});
function editComment(postId,id){const post=data.posts.find(p=>p.id===postId),comment=post?.comments?.find(c=>c.id===id);if(!comment)return;modal(`<form id="editCommentForm"><h2>修改这条想法</h2><label class="field" for="editCommentBody">评论正文</label><textarea id="editCommentBody" required maxlength="20000">${esc(comment.body)}</textarea>${endForm}`);$('editCommentForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const body=$('editCommentBody').value.trim();if(!body)return toast('评论不能为空。');const next=clone(),target=next.posts.find(p=>p.id===postId)?.comments?.find(c=>c.id===id);if(!target)return toast('这条评论已不存在。');target.body=body;target.updated=new Date().toISOString();busy=true;openedComments.add(postId);try{if(await commit(next)){$('dialog').close();toast('评论已更新。')}}finally{busy=false}}}
function deleteComment(postId,id){modal('<h2>删除这条评论？</h2><p>只删除这条补充想法，帖子正文会保留。删除后无法撤销。</p><div class="dialogActions"><button data-action="close">取消</button><button class="primary" id="confirmDeleteComment">确认删除</button></div>');$('confirmDeleteComment').onclick=async()=>{if(busy)return;const next=clone(),p=next.posts.find(p=>p.id===postId);if(!p)return;p.comments=(p.comments||[]).filter(c=>c.id!==id);busy=true;openedComments.add(postId);try{if(await commit(next))$('dialog').close()}finally{busy=false}}}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;const d=button.dataset;if(d.expandPost){const post=data.posts.find(p=>p.id===d.expandPost);if(!post)return;const expanded=!expandedPosts.has(post.id);if(expanded)expandedPosts.add(post.id);else expandedPosts.delete(post.id);const body=document.getElementById('post-body-'+post.id);body.innerHTML=richText(expanded?post.body:bodyPreview(post.body).text)+(expanded?'':'…');button.setAttribute('aria-expanded',String(expanded));button.textContent=expanded?'收起正文':'展开全文（超过 '+POST_PREVIEW_LIMIT+' 字）'}if(d.editComment)editComment(d.commentPost,d.editComment);if(d.deleteComment)deleteComment(d.commentPost,d.deleteComment)});
window.addEventListener('DOMContentLoaded',installDateFilter);
